const TB_FLK=[{"par": 5, "tip": "\u201cThe Farm.\u201d A 576-yard par 5 that bends gently right. Two bunkers pinch the landing area. Two bunkers guard the green on both sides.", "green": {"elev": 1.0, "spine": 0.5, "tier": 0}, "slope": [0.27, -0.31], "bumps": []}, {"par": 4, "tip": "\u201cSawmill.\u201d A 416-yard par 4 that bends gently right. A bunker guards the green on the right. Water sits left of the green.", "green": {"elev": 1.3, "spine": 0.5, "tier": 0}, "slope": [0.02, -0.09], "bumps": []}, {"par": 4, "tip": "\u201cBaby Rattler.\u201d A 354-yard par 4 that plays straight away. A bunker guards the green on the right.", "green": {"elev": 0.7, "spine": 0.5, "tier": 0}, "slope": [0.15, 0.19], "bumps": []}, {"par": 4, "tip": "\u201cLower 40.\u201d The hardest hole on the course climbs to a green perched on the hillside, with a stream crossing the fairway. A 472-yard par 4 that plays straight away. Two bunkers guard the green on both sides.", "green": {"elev": 1.0, "spine": 0.5, "tier": 0}, "slope": [0.01, 0.11], "bumps": []}, {"par": 3, "tip": "\u201cHang Time.\u201d The signature hole: the tee sits on a hilltop near an old marble quarry, about 170 feet above the green. A 206-yard par 3. Three bunkers guard the green on both sides.", "green": {"elev": 1.3, "spine": 0.8, "tier": 0}, "slope": [0.09, 0.2], "bumps": []}, {"par": 5, "tip": "\u201cBootlegger.\u201d Downhill off the tee, then back up to a perched green that falls away left and long. A 530-yard par 5 that bends gently left. Two bunkers pinch the landing area. Two bunkers guard the green on both sides.", "green": {"elev": 0.9, "spine": 0.8, "tier": 0.6}, "slope": [-0.17, -0.28], "bumps": []}, {"par": 4, "tip": "\u201cBig Daddy.\u201d A 426-yard par 4 that plays straight away. Two bunkers pinch the landing area. Two bunkers guard the green on both sides.", "green": {"elev": 0.9, "spine": 0.8, "tier": 0}, "slope": [-0.13, -0.09], "bumps": []}, {"par": 3, "tip": "\u201cBack It Up.\u201d Long but downhill and open; a miss short leaves a fair chip. A 250-yard par 3. A bunker guards the green on the left.", "green": {"elev": 0.8, "spine": 0, "tier": 0}, "slope": [-0.24, -0.08], "bumps": []}, {"par": 4, "tip": "\u201cDesoto.\u201d A 451-yard par 4 that doglegs hard right. One bunker pinches the landing area. A bunker guards the green on the left. Water sits right of the green.", "green": {"elev": 1.1, "spine": 0.5, "tier": 0}, "slope": [-0.18, 0.17], "bumps": []}, {"par": 5, "tip": "\u201cChristine.\u201d Lake Christine sits right of the tee shot; the fairway is wide. A 533-yard par 5 that doglegs hard right. Three bunkers pinch the landing area. Two bunkers guard the green on both sides. Water sits right of the hole.", "green": {"elev": 1.3, "spine": 0.5, "tier": 0.6}, "slope": [0.02, -0.14], "bumps": []}, {"par": 4, "tip": "\u201cLonely Pine.\u201d A lone pine stands in the fairway; the best line is just left of it. A 428-yard par 4 that bends gently left. A bunker guards the green on the right.", "green": {"elev": 0.9, "spine": 0.8, "tier": 0}, "slope": [0.08, -0.31], "bumps": []}, {"par": 4, "tip": "\u201cEureka Railroad.\u201d The old Eureka railroad bed runs through the right greenside bunker. A 467-yard par 4 that doglegs hard left. Two bunkers pinch the landing area. Two bunkers guard the green on both sides.", "green": {"elev": 0.7, "spine": 0, "tier": 0.6}, "slope": [-0.27, -0.22], "bumps": []}, {"par": 4, "tip": "\u201cGo For It.\u201d Short and tempting: the risk-reward hole. A 369-yard par 4 that bends gently left. A bunker guards the green on the left.", "green": {"elev": 1.0, "spine": 0.8, "tier": 0}, "slope": [-0.15, -0.16], "bumps": []}, {"par": 4, "tip": "\u201cSwamp.\u201d The flattest hole, with Pennywinkle Creek and the woods all down the left. A 434-yard par 4 that plays straight away. One bunker pinches the landing area. Two bunkers guard the green on both sides. Water sits right of the hole.", "green": {"elev": 0.9, "spine": 0.5, "tier": 0}, "slope": [-0.2, 0.19], "bumps": []}, {"par": 3, "tip": "\u201cShowcase.\u201d A 223-yard par 3. Two bunkers guard the green on both sides.", "green": {"elev": 1.4, "spine": 0.8, "tier": 0}, "slope": [-0.26, 0.18], "bumps": []}, {"par": 4, "tip": "\u201cDana's Pick.\u201d Doglegs right and climbs to a perched, heavily contoured green. A 396-yard par 4 that bends gently right. One bunker pinches the landing area. Two bunkers guard the green on both sides.", "green": {"elev": 1.0, "spine": 0.8, "tier": 0}, "slope": [0.14, -0.22], "bumps": []}, {"par": 3, "tip": "\u201cBig Gulp.\u201d Over the pond to the green, with hardwoods behind. A 187-yard par 3. A bunker guards the green on the right. Water sits left of the green.", "green": {"elev": 1.3, "spine": 0, "tier": 0}, "slope": [-0.14, 0.18], "bumps": []}, {"par": 5, "tip": "\u201cOrchards.\u201d A long, slightly uphill finish through the old orchard, with the Grille looking over the green. A 607-yard par 5 that plays straight away. One bunker pinches the landing area. A bunker guards the green on the left.", "green": {"elev": 1.0, "spine": 0, "tier": 0}, "slope": [-0.15, 0.05], "bumps": []}];
