const TURF_DEF={fw:[0,1,1],ro:[0,1,1],gr:[0,1,1],te:[0,1,1],st:[11,1,0,1],k:[1,1,1,1],sand:'#f4efe2',sp:'b'};
const turfOf=()=>TURF[CUR&&CUR.id]||TURF_DEF;
function turfRGB(hex,a){let r,g,b;if(Array.isArray(hex))[r,g,b]=hex.map(v=>v/255);else{const n=parseInt(hex.slice(1),16);r=(n>>16&255)/255;g=(n>>8&255)/255;b=(n&255)/255;}
  const mx=Math.max(r,g,b),mn=Math.min(r,g,b);let h=0,l=(mx+mn)/2,s=0;const d=mx-mn;
  if(d>1e-6){s=l>.5?d/(2-mx-mn):d/(mx+mn);h=mx===r?((g-b)/d+(g<b?6:0)):mx===g?((b-r)/d+2):((r-g)/d+4);h/=6;}
  if(a){h=(h+a[0]/360+1)%1;s=Math.min(1,s*a[1]);l=Math.min(.97,l*a[2]);}
  const f=t=>{t=(t+1)%1;const q=l<.5?l*(1+s):l+s-l*s,p=2*l-q;return t<1/6?p+(q-p)*6*t:t<.5?q:t<2/3?p+(q-p)*(2/3-t)*6:p;};
  return s<1e-6?[l,l,l].map(v=>Math.round(v*255)):[f(h+1/3),f(h),f(h-1/3)].map(v=>Math.round(v*255));}
const turfHex=(hex,a)=>'#'+turfRGB(hex,a).map(v=>v.toString(16).padStart(2,'0')).join('');
/* two stripe shades around their middle, with the course's contrast */
function turfPair(c1,c2,a,k){const A=turfRGB(c1,a),B=turfRGB(c2,a);const m=A.map((v,i)=>(v+B[i])/2);const h=x=>'#'+x.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');
  return[h(m.map((v,i)=>v+(A[i]-v)*k)),h(m.map((v,i)=>v+(B[i]-v)*k))];}
